#!/usr/bin/env node
'use strict';
/* =============================================================================
 * arch_check.cjs - hold a repo's DECLARED architecture against its REAL code and config. Every repo runs it, no Python.
 * Jennifer 19-Nov-2026: "github should have something we build off right for all repos or spaces in the repos",
 * "remember never .md only code". Prose architecture went silently stale again and again; this goes red instead.
 *
 * THE DECLARATION is .ci/architecture.json. It is GENERATED by agency-os-agents tools/ci_fleet_sync.cjs from
 * brain/manifests/*.json (the ONE canonical worker and component declaration, schema
 * brain/schema/agent.manifest.schema.json). Never edit it in the repo: edit the manifest there and re-run the sync.
 *
 * WHAT IS READ (the real thing, never the declaration's say-so)
 *   wrangler.toml / wrangler.json / wrangler.jsonc in the component's root: name, main, routes, crons, var NAMES,
 *     kv, r2, d1, durable objects, queues, ai, service bindings
 *   every JS/TS file reachable from `main` by relative import: env.X reads (secret NAMES = reads that are neither a
 *     var nor a binding) and *.workers.dev hosts called (a known worker reached by URL is an edge)
 *   any wrangler config in the repo that no component claims (a Worker nobody declared)
 *   registry.json at the repo root, when the declaration carries fleetWorkers (the cloudflare-workers repo)
 *
 * FOUR VERDICTS, NEVER TWO
 *   PASS          read, and it is as declared
 *   FAIL          read, and it differs: declared but absent, or present but undeclared
 *   UNKNOWN       could not tell (destructured or computed env access, a runtime with no reader, no wrangler block
 *                 declared). Never a pass.
 *   NOT DECLARED  the repo has no .ci/architecture.json
 * EXIT  advisory until the declaration's ratchet date (default ARCH_RATCHET below): always 0, verdicts printed.
 *       From that date: 1 on any FAIL or NOT DECLARED; UNKNOWN alone stays 0 and is printed as not proved.
 *       2 could not run (bad arguments, unparseable declaration).
 *
 * RUN   node .ci/arch_check.cjs [--root <repoDir>] [--json] [--today YYYY-MM-DD]
 *       node .ci/arch_check.cjs --scaffold <componentDir>     print a wrangler block MEASURED from the config (backfill)
 *       node .ci/arch_check.cjs --self-test [--json]          planted trees: every rule must flip
 * NO REGEX (house rule 2026-09-08). No dependencies.
 * ============================================================================= */
const fs = require('fs'), path = require('path'), os = require('os');

const ARCH_RATCHET = '2026-12-19';
const SCHEMA = 'optimisers-architecture/v1';
const SKIP_DIRS = new Set(['node_modules', '.git', '.wrangler', '.ci-dist', 'dist', '.out', '_Archive']);
const WRANGLER_NAMES = ['wrangler.toml', 'wrangler.jsonc', 'wrangler.json'];
const CODE_EXT = ['.js', '.mjs', '.cjs', '.ts', '.mts'];
const BINDING_KINDS = ['kv', 'r2', 'd1', 'durable_objects', 'queues', 'ai'];

// ---------------------------------------------------------------- small helpers
