    if (decl.schema !== SCHEMA) throw new Error('.ci/architecture.json schema is ' + JSON.stringify(decl.schema) + ', expected ' + SCHEMA);
    const ratchet = decl.ratchet || ARCH_RATCHET;
    const comps = decl.components || [];
    const sub = decl.workersDevSubdomain || '';
